#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PolicyAutonomyCopilotReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub disposition:String,pub action_order:Vec<String>,pub admitted_action_order:Vec<String>,pub denied_action_order:Vec<String>,pub policy_disposition:String,pub policy_digest:ContentHash,pub copilot_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
