impl PolicyAutonomyCopilotReceipt{pub fn validate(&self)->Result<(),PolicyAutonomyCopilotError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.action_order.is_empty()||![&self.policy_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(h){return Err(PolicyAutonomyCopilotError::Receipt("policy_autonomy copilot identity or digest is incomplete".into()));}for v in [&self.action_order,&self.admitted_action_order,&self.denied_action_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(PolicyAutonomyCopilotError::Receipt("policy_autonomy copilot vectors are not canonical".into()));}}let ids=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.admitted_action_order.iter().chain(&self.denied_action_order).cloned().collect::<BTreeSet<_>>();if ids!=p||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.copilot_digest.as_str()){return Err(PolicyAutonomyCopilotError::Receipt("policy_autonomy copilot actions do not partition".into()));}Ok(())}}
