pub fn run(r:&PolicyAutonomyCopilotRequest,feature_id:&str,version:&str,_scale:&str,require_approval:bool,_federation:bool)->Result<PolicyAutonomyCopilotReceipt,PolicyAutonomyCopilotError>{if r.boundary!=PRECLINICAL_BOUNDARY||r.action_order.is_empty()||r.action_order!={let mut x=r.action_order.clone();x.sort();x.dedup();x}||r.action_budget==0||!r.policy_autonomy_request.raw_data_local||!r.policy_autonomy_request.federated_summary_only{return Err(PolicyAutonomyCopilotError::Invalid("policy_autonomy copilot request is invalid".into()))}let policy_autonomy=policy_autonomy_support::qualify(&r.policy_autonomy_request,feature_id,version).map_err(|e|PolicyAutonomyCopilotError::Release(e.to_string()))?;let mut omissions=policy_autonomy.omission_order.clone();let approved=!require_approval||r.signed_approval;if !approved{omissions.push("copilot:approval-missing".into())}if r.dry_run{omissions.push("copilot:dry-run-no-effect".into())}if r.action_order.len()as u64>r.action_budget{omissions.push("copilot:action-budget-exceeded".into())}omissions.sort();omissions.dedup();let safe=policy_autonomy.disposition=="qualified"&&approved&&r.action_order.len()as u64<=r.action_budget;let disposition=if safe{"qualified"}else if policy_autonomy.disposition=="blocked"||!approved{"blocked"}else{"partial"};let admitted=if safe{r.action_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{r.action_order.clone()};let effects=if disposition=="blocked"{vec!["block:unsafe-policy_autonomy".into()]}else{vec![format!("invoke:bounded-policy_autonomy-tool:{}",policy_autonomy.receipt_digest)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":r.policy_autonomy_request.request_id,"disposition":disposition,"action_order":r.action_order,"admitted_action_order":admitted,"denied_action_order":denied,"policy_disposition":policy_autonomy.disposition,"policy_digest":policy_autonomy.receipt_digest,"replay_identity":policy_autonomy.replay_identity,"omissions":omissions,"uncertainty":policy_autonomy.uncertainty_order,"negative_evidence":policy_autonomy.negative_evidence_order,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|PolicyAutonomyCopilotError::Artifact(e.to_string()))?;let out=PolicyAutonomyCopilotReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:r.policy_autonomy_request.request_id.clone(),disposition:disposition.into(),action_order:r.action_order.clone(),admitted_action_order:admitted,denied_action_order:denied,policy_disposition:policy_autonomy.disposition,policy_digest:policy_autonomy.receipt_digest,copilot_digest:d.clone(),replay_identity:policy_autonomy.replay_identity,omissions:payload["omissions"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),uncertainty:policy_autonomy.uncertainty_order,negative_evidence:policy_autonomy.negative_evidence_order,effect_receipts:effects,artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
